begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('09000000-0000-4000-8000-000000000001','schedule-owner@example.test',now()),('09000000-0000-4000-8000-000000000002','schedule-admin@example.test',now()),('09000000-0000-4000-8000-000000000003','schedule-barber@example.test',now()),('09000000-0000-4000-8000-000000000004','schedule-other@example.test',now());
insert into public.businesses(id,slug,name) values('19000000-0000-4000-8000-000000000001','schedule-alpha','Schedule A'),('19000000-0000-4000-8000-000000000002','schedule-beta','Schedule B');
insert into public.business_settings(business_id,min_notice_minutes) values('19000000-0000-4000-8000-000000000001',0),('19000000-0000-4000-8000-000000000002',0);
insert into public.business_members(id,business_id,user_id,role) values('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','09000000-0000-4000-8000-000000000001','owner'),('29000000-0000-4000-8000-000000000002','19000000-0000-4000-8000-000000000001','09000000-0000-4000-8000-000000000002','admin'),('29000000-0000-4000-8000-000000000003','19000000-0000-4000-8000-000000000001','09000000-0000-4000-8000-000000000003','barber'),('29000000-0000-4000-8000-000000000004','19000000-0000-4000-8000-000000000002','09000000-0000-4000-8000-000000000004','owner');
insert into public.staff_members(id,business_id,member_id,display_name) values('39000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000003','Own staff'),('39000000-0000-4000-8000-000000000002','19000000-0000-4000-8000-000000000001',null,'Other staff');
insert into public.services(id,business_id,name,price_cents,duration_minutes,buffer_minutes) values('49000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','Fixture',10000,30,10);
insert into public.staff_services(business_id,staff_member_id,service_id,duration_override_minutes) values('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000001',45);
select set_config('test.day',((clock_timestamp() at time zone 'America/Argentina/Buenos_Aires')::date+1)::text,true);
select ok((select count(*)=6 and bool_and(relrowsecurity and relforcerowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where (n.nspname,c.relname) in (('app','calendar_controls'),('public','staff_working_plans'),('public','working_hours'),('public','schedule_exceptions'),('public','time_blocks'),('app','schedule_requests'))),'six scheduling tables force RLS');
select ok(not exists(select 1 from unnest(array['anon','authenticated','app_server','service_role']) r cross join unnest(array['app.calendar_controls','public.staff_working_plans','public.working_hours','public.schedule_exceptions','public.time_blocks','app.schedule_requests']) t where has_table_privilege(r,t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')),'no direct application table grants');
select ok(app.schedule_instant('2024-03-10',150,'America/New_York') is null,'spring gap not shifted');
select is(app.schedule_instant('2024-11-03',90,'America/New_York'),'2024-11-03T05:30:00Z'::timestamptz,'fall fold first occurrence');
select ok(app.schedule_instant('2024-10-06',135,'Australia/Lord_Howe') is null,'half-hour DST gap');
select is(app.schedule_instant('2024-04-07',105,'Australia/Lord_Howe'),'2024-04-06T14:45:00Z'::timestamptz,'half-hour fold first occurrence');
select is(app.schedule_instant('2024-01-01',0,'Asia/Kathmandu'),'2023-12-31T18:15:00Z'::timestamptz,'midnight and fractional timezone');
select ok(app.schedule_instant('2011-12-30',720,'Pacific/Apia') is null,'skipped civil day has no synthetic instant');
select is(app.schedule_intervals('[{"start_minute":540,"end_minute":600},{"start_minute":600,"end_minute":660}]',false),'[{"start_minute":540,"end_minute":660}]'::jsonb,'contiguous intervals canonicalized');
select throws_ok($$select app.schedule_intervals('[{"start_minute":540,"end_minute":660},{"start_minute":600,"end_minute":720}]',false)$$,'PT400','VALIDATION_ERROR','overlapping intervals denied');
set local role authenticated;set local "request.jwt.claim.sub"='09000000-0000-4000-8000-000000000003';set local "request.jwt.claims"='{"aal":"aal1"}';
select is(jsonb_array_length(api.list_schedule_staff('19000000-0000-4000-8000-000000000001')),1,'barber lists demonstrably owned staff only');
select throws_ok($$select api.read_schedule('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000002')$$,'PT404','NOT_FOUND','barber cannot read another staff schedule');
select throws_ok($$select api.write_schedule('19000000-0000-4000-8000-000000000001',null,'exception',gen_random_uuid(),'save','{}',gen_random_uuid(),null)$$,'PT403','FORBIDDEN','barber write denied before payload or preconditions');
set local "request.jwt.claim.sub"='09000000-0000-4000-8000-000000000001';
select throws_ok($$select api.read_calendar_control('19000000-0000-4000-8000-000000000001')$$,'PT403','MFA_REQUIRED','owner needs MFA');
set local "request.jwt.claims"='{"aal":"aal2"}';
select is(api.read_calendar_control('19000000-0000-4000-8000-000000000001')->>'version','1','global control virtual version one');
select is(api.write_schedule('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','plan','59000000-0000-4000-8000-000000000001','save',jsonb_build_object('effective_from',current_setting('test.day'),'intervals',(select jsonb_agg(jsonb_build_object('weekday',n,'start_minute',540,'end_minute',1080)) from generate_series(1,7)n)),'69000000-0000-4000-8000-000000000001',1)->>'version','2','weekly plan increments staff once');
select is(api.write_schedule('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','plan','59000000-0000-4000-8000-000000000001','save',jsonb_build_object('effective_from',current_setting('test.day'),'intervals',(select jsonb_agg(jsonb_build_object('weekday',n,'start_minute',540,'end_minute',1080)) from generate_series(1,7)n)),'69000000-0000-4000-8000-000000000001',1)->>'version','2','plan replay one effect');
select is(api.schedule_preview_source('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000001',current_setting('test.day'))->>'duration_minutes','45','preview uses staff override');
select is(api.schedule_preview_source('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000001',current_setting('test.day'))->>'can_book','false','preview never grants booking');
select is(api.write_schedule('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','exception','59000000-0000-4000-8000-000000000002','save',jsonb_build_object('date',current_setting('test.day'),'kind','custom_hours','intervals','[{"start_minute":600,"end_minute":660}]'::jsonb,'reason','Private fixture reason'),gen_random_uuid(),2)->>'version','3','individual exception uses staff parent');
select is(api.write_schedule('19000000-0000-4000-8000-000000000001',null,'exception','59000000-0000-4000-8000-000000000003','save',jsonb_build_object('date',current_setting('test.day'),'kind','closed','intervals','[]'::jsonb,'reason','Private global reason'),gen_random_uuid(),1)->>'version','2','first global write creates version two');
select is(api.schedule_preview_source('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000001',current_setting('test.day'))->'days'->0->'intervals','[]'::jsonb,'global closure overrides personal opening');
select is(api.write_schedule('19000000-0000-4000-8000-000000000001',null,'exception','59000000-0000-4000-8000-000000000003','archive','{}',gen_random_uuid(),2)->>'version','3','retiring global exception uses independent version');
set local "request.jwt.claim.sub"='09000000-0000-4000-8000-000000000003';set local "request.jwt.claims"='{"aal":"aal1"}';
select ok(not (api.read_schedule('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001')->'exceptions'->0 ? 'reason'),'barber projection has no private reason');
select is(api.schedule_preview_source('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000001',current_setting('test.day'))->>'occupancy_checked','true','barber own preview checks actual occupancy');
set local "request.jwt.claim.sub"='09000000-0000-4000-8000-000000000004';set local "request.jwt.claims"='{"aal":"aal2"}';
select throws_ok($$select api.read_schedule('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001')$$,'PT404','NOT_FOUND','cross tenant schedule denied');
reset role;
select is((select version from public.staff_members where id='39000000-0000-4000-8000-000000000001'),3,'global writes do not bump every staff');
select is((select count(*) from public.audit_logs where business_id='19000000-0000-4000-8000-000000000001'),4::bigint,'audit once per new mutation, never replay');
select ok(not exists(select 1 from app.schedule_requests where result::text like '%Private%'),'private reasons absent from replay');
select throws_ok('select app.purge_schedule_requests(501)','PT400','VALIDATION_ERROR','bounded private schedule purger');
select throws_ok($$update public.working_hours set start_minute=600 where business_id='19000000-0000-4000-8000-000000000001'$$,'PT409','IMMUTABLE_PLAN','published interval cannot be rewritten');
select throws_ok($$insert into public.working_hours(business_id,plan_id,position,weekday,start_minute,end_minute) values('19000000-0000-4000-8000-000000000001','59000000-0000-4000-8000-000000000001',99,1,600,700)$$,'PT409','INTERVAL_OVERLAP','row-level overlap defense');
select throws_ok($$insert into public.working_hours(business_id,plan_id,position,weekday,start_minute,end_minute) values('19000000-0000-4000-8000-000000000002','59000000-0000-4000-8000-000000000001',99,1,600,700)$$,'23503',null,'composite FK rejects foreign plan');
create function pg_temp.fail_schedule_audit() returns trigger language plpgsql as $$begin if new.action like 'schedule.%' then raise exception 'FIXTURE_FAILURE';end if;return new;end;$$;
create trigger fixture_schedule_failure before insert on public.audit_logs for each row execute function pg_temp.fail_schedule_audit();
set local role authenticated;set local "request.jwt.claim.sub"='09000000-0000-4000-8000-000000000001';
select throws_ok($$select api.write_schedule('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','plan','59000000-0000-4000-8000-000000000009','save',jsonb_build_object('effective_from',current_setting('test.day'),'intervals','[]'::jsonb),gen_random_uuid(),3)$$,'P0001','FIXTURE_FAILURE','audit failure rolls back supersession and parent');
reset role;
select is((select count(*) from public.staff_working_plans where business_id='19000000-0000-4000-8000-000000000001' and superseded_at is null),1::bigint,'rollback preserves old live plan');
select is((select version from public.staff_members where id='39000000-0000-4000-8000-000000000001'),3,'rollback preserves parent version');
drop trigger fixture_schedule_failure on public.audit_logs;
set local role authenticated;
select is(api.write_schedule('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','plan','59000000-0000-4000-8000-000000000004','save',jsonb_build_object('effective_from',(current_setting('test.day')::date+2)::text,'intervals','[]'::jsonb),gen_random_uuid(),3)->>'version','4','future closed plan uses same parent');
select is(api.schedule_preview_source('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000001',(current_setting('test.day')::date+2)::text)->'days'->0->'intervals','[]'::jsonb,'empty future plan closes only from its effective date');
select is(api.write_schedule('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','plan','59000000-0000-4000-8000-000000000005','save',jsonb_build_object('effective_from',(current_setting('test.day')::date+2)::text,'intervals','[]'::jsonb),gen_random_uuid(),4)->>'version','5','future revision can be superseded without rewriting intervals');
select is(api.write_schedule('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','block','59000000-0000-4000-8000-000000000006','save',jsonb_build_object('start_date',current_setting('test.day'),'start_minute',600,'end_date',current_setting('test.day'),'end_minute',610,'kind','manual','reason','Private block'),gen_random_uuid(),5)->>'version','6','block converted in business timezone');
select is(api.write_schedule('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','block','59000000-0000-4000-8000-000000000006','archive','{}',gen_random_uuid(),6)->>'version','7','block retirement versioned and logical');
select throws_ok($$select api.write_schedule('19000000-0000-4000-8000-000000000001','39000000-0000-4000-8000-000000000001','plan',gen_random_uuid(),'save',jsonb_build_object('effective_from',(current_setting('test.day')::date-2)::text,'intervals','[]'::jsonb),gen_random_uuid(),7)$$,'PT400','VALIDATION_ERROR','past plan denied');
reset role;
select is((select count(*) from public.staff_working_plans where business_id='19000000-0000-4000-8000-000000000001'),3::bigint,'all plan revisions preserved');
select is((select count(*) from public.staff_working_plans where business_id='19000000-0000-4000-8000-000000000001' and superseded_at is null),2::bigint,'current and future dates preserved independently');
select is((select count(*) from public.time_blocks where business_id='19000000-0000-4000-8000-000000000001' and deleted_at is not null),1::bigint,'retired block history retained');
select ok(not has_function_privilege('authenticated','app.purge_schedule_requests(integer)','EXECUTE'),'maintenance never exposed');
update app.schedule_requests set created_at=clock_timestamp()-interval '49 hours' where key='69000000-0000-4000-8000-000000000001';
select is(app.purge_schedule_requests(500),1,'physical retention affects only expired schedule replay');
select * from finish();rollback;
